# -*- coding: utf-8 -*-
"""Издания третьей очереди добора (отобраны вручную из других разделов библиотеки): описание задано по титульному листу,
прочитанному в файле. Там, где титульного листа в файле нет, так и сказано в поле how. Запуск после books5.py, до sort5d.py."""
import os, sys, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import ROOT, D5
os.chdir(ROOT)
T = 'титульный лист (описание составлено вручную)'
NT = 'название — по содержанию и записи каталога библиотеки («%s»): титульного листа в файле нет'
FIX = {'tsp': {
 'sb9b79cd': ('Княжев, Грищенко и др.', 'Топографическое и картографическое обеспечение органов внутренних дел Российской Федерации', 'учебник', 'Академия управления МВД', 2024, T),
 'sbec6f29': ('Панасик', 'Условные знаки. Служебные графические документы органов внутренних дел', 'учебное наглядное пособие', 'КЮИ МВД', 2010, NT % 'Панасик Усл.знаки'),
 'sbcf2d26': ('Панасик', 'Защита от современных средств поражения', 'учебное пособие', 'КЮИ МВД', 2011, NT % 'Панасик Защита от соврем средств пораж'),
 'sb5ed8d8': ('', 'Актуальные вопросы совершенствования специальной подготовки курсантов и слушателей образовательных организаций системы МВД России', 'материалы всерос. науч.-практ. конф. (28 марта 2024 г.)', 'КрУ МВД', 2024, T),
 'sb9edec6': ('Огородников, Князев и др.', 'Деятельность органов внутренних дел в чрезвычайных ситуациях мирного и военного времени', 'учебное пособие', 'ОмА МВД', 2022, T),
 'sb6b7724': ('Осипов, Коряковцев и др.', 'Деятельность органов внутренних дел при возникновении чрезвычайных обстоятельств', 'учебно-практическое пособие', 'НА МВД', 2022, T + '; страницы файла — изображения, текстового слоя нет'),
 'sbae5d9c': ('Калинников, Козлов', 'Средства обеспечения специальных операций', 'учебно-практическое пособие', 'Калининградский филиал СПбУ МВД', 2020, T),
 'sbda2eff': ('Никулин', 'Основы тактико-специальной подготовки и личной безопасности сотрудников войск национальной гвардии', 'курс лекций', 'КЮИ МВД', 2022, T),
 'sb0921cf': ('Горлов, Родионов, Мельник', 'Тактико-специальная подготовка (для самостоятельной работы слушателей факультета заочного обучения)', 'методические рекомендации', 'ВИ МВД', 2025, T),
}}
for code, fx in FIX.items():
    P = D5 + 'books_%s.json' % code; B = json.load(open(P, encoding='utf-8')); n = 0
    for b in B:
        f = fx.get(b['n'])
        if not f: continue
        b.update(authors=f[0], title=f[1], kind=f[2], pub=f[3], year=f[4], how=f[5], off=False); n += 1
    json.dump(B, open(P, 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    print(code, 'описано вручную:', n)
